        for b0, b1 in bands[i + 1:]:
            if a1 - a0 != b1 - b0:
                continue
            for d in range(-3, 4):  # B[c+d] aligns with A[c]
                inter = union = 0
                for k in range(a1-a0):
                    for c in range(w):
